void kvdb_type_blob_sample(fdb_kvdb_t kvdb)
{
    struct fdb_blob blob;
    
    FDB_INFO("==================== kvdb_type_blob_sample ====================\n");

    { /* CREATE new Key-Value */
        int temp_data = 37;

        /* It will create new KV node when "temp" KV not in database.
         * fdb_blob_make: It's a blob make function, and it will return the blob when make finish.
         */
        fdb_kv_set_blob(kvdb, "temp", fdb_blob_make(&blob, &temp_data, sizeof(temp_data)));
        FDB_INFO("create the 'temp' blob KV, value is: %d\n", temp_data);
    }

    { /* GET the KV value */
        int temp_data = 0;

        /* get the "temp" KV value */
        fdb_kv_get_blob(kvdb, "temp", fdb_blob_make(&blob, &temp_data, sizeof(temp_data)));
        /* the blob.saved.len is more than 0 when get the value successful */
        if (blob.saved.len > 0) {
            FDB_INFO("get the 'temp' value is: %d\n", temp_data);
        }
    }

  
				for(uint32_t i=0;i<12;i++)
				{
					//Start_Watchpoint();
					uint32_t rand= rng_get_random();
				  fdb_kv_set_blob(kvdb, epcidkey[i], fdb_blob_make(&blob, &rand, sizeof(rand)));
				//	uint32_t tick=measure_execution_time();
				//	printf("epcid set %s,value is: %d timecost:%d\n",epcidkey[i],rand,tick);
					//FlashDB_Sync_flag++;
				}
				
					for(uint32_t i=0;i<12;i++)
				{
					uint32_t rand= 0;
				  fdb_kv_get_blob(kvdb, epcidkey[i], fdb_blob_make(&blob, &rand, sizeof(rand)));
				  printf("epcid get %s,value is: %d \n",epcidkey[i],rand); 
				}
    

    { /* DELETE the KV by name */
        fdb_kv_del(kvdb, "694182786475522001000001");
        FDB_INFO("delete the 'temp' finish\n");
    }

    FDB_INFO("===========================================================\n");
}

void save_tag_flashDB(fdb_kvdb_t kvdb, LTDataType  epcid,uint8_t method)
{
 static struct fdb_blob blob;
	uint32_t rand= 0xAA;
	char epcstr[64];
	 Hex2Str(epcid.epc,epcid.Epclen, epcstr);
	if(method==2)
	{	
  fdb_kv_set_blob(kvdb, epcstr, fdb_blob_make(&blob, &rand, sizeof(rand)));
 // TRACE("create the %s blob KV, value is: %d  sync flag=%d \n",epcstr, rand,FlashDB_Sync_flag);
  }	
 if(method==3)
	{	
  fdb_kv_del(kvdb, epcstr);
 // TRACE("delete epcid= %s  \n",epcstr);
  }			
}

extern LTNode* taglist;
void kvdb_tarversal_total(fdb_kvdb_t kvdb)
{
    struct fdb_kv_iterator iterator;
    fdb_kv_t cur_kv;
    struct   fdb_blob blob;
    size_t   data_size;
    uint8_t  *data_buf;
	  LTDataType epcID;
	  uint8_t   wepclenth=0;
	  uint8_t   tmpbuf[64];
    fdb_kv_iterator_init(kvdb, &iterator);
    LTClear(taglist);
    while (fdb_kv_iterate(kvdb, &iterator)) {
        cur_kv = &(iterator.curr_kv);
        data_size = (size_t) cur_kv->value_len;
        data_buf = (uint8_t *) malloc(data_size);
        if (data_buf == NULL) {
            FDB_INFO("Error: malloc failed.\n");
            break;
        }
        fdb_blob_read((fdb_db_t) kvdb, fdb_kv_to_blob(cur_kv, fdb_blob_make(&blob, data_buf, data_size)));
        /*
         * balabala do what ever you like with blob...
         */
         if((*(uint32_t *)data_buf)==0xAA &&  cur_kv->name_len<32)
				 {
				  memset(&epcID,0,sizeof(epcID));	
				  wepclenth =cur_kv->name_len;
					Str2Hex(cur_kv->name,wepclenth, (unsigned char *)tmpbuf); 
					wepclenth = wepclenth / 2; 
					memcpy(epcID.epc, tmpbuf, wepclenth);
          epcID.Epclen = wepclenth;
          tagtable_list_update(taglist,epcID,OPTION_ADD);	 
				 } 
			//	FDB_INFO("show the %s blob KV, value is: %d, epc tag count=%d\n",cur_kv->name,*(uint32_t *)data_buf,epccnts++); 
        free(data_buf);
    }
		
		 
}

uint32_t Match_EPC_inDB(fdb_kvdb_t kvdb,uint8_t *input_tag, uint16_t tlen)
{
  	char epcstr[64];
	  Hex2Str(input_tag,tlen, epcstr);
	  
    { /* GET the KV value */
         uint32_t rand= 0;
         struct fdb_blob blob;
        /* get the "temp" KV value */
        fdb_kv_get_blob(kvdb, epcstr, fdb_blob_make(&blob, &rand, sizeof(rand)));
        /* the blob.saved.len is more than 0 when get the value successful */
        if (blob.saved.len > 0) {
            FDB_INFO("get the '%s' value is: %d\n", epcstr,rand);
					  return 1;
        }
    }
		
		return 0;
}	

